try:
    from collections.abc import Iterable, Iterator
except ImportError:
    from collections import Iterable, Iterator


class ConnectionIterator(Iterator):
    def __init__(self, connection_list):
        self._connection_list = connection_list
        self._index = 0

    def __next__(self):
        if self._index == len(self._connection_list):
            raise StopIteration

        result = self._connection_list[self._index]
        self._index += 1
        return result

    next = __next__


class ConnectionDataResult(Iterable):
    def __init__(self, connection_id=None):
        self.connection_id = connection_id if connection_id else None
        self.peak = None
        self.minimum = None
        self.count = 0
        self.total = None

    def __iter__(self):
        return ConnectionIterator([self])

    def to_dict(self):
        return {'connection': self.total.header.connections[self.connection_id].to_dict(),
                'peak': self.peak.to_dict(), 'average': self.average.to_dict(),
                'minimum': self.minimum.to_dict(), 'count': self.count,
                'interval': self.total.interval.diff}

    def __str__(self):
        return str(self.to_dict())

    @property
    def average(self):
        if not self.total:
            return 0
        if self.total.is_per_sec_value():
            return self.total
        else:
            return self.total / self.total.interval.diff

    def reset(self):
        self.peak = None
        self.minimum = None
        self.count = 0
        self.total = None


class MultipleConnectionDataResult(Iterable):
    def __init__(self, connection_data_results):
        self._connection_data_results = connection_data_results

    def __iter__(self):
        return ConnectionIterator(self._connection_data_results)

    def reset(self):
        for connection_data_result in self._connection_data_results:
            connection_data_result.reset()


class ConnectionDataItem(object):
    def __init__(self, connection_id, current):
        self._connection_id = connection_id
        self._current = current
        self._result = ConnectionDataResult(connection_id)

    @property
    def connection_id(self):
        return self._connection_id

    @property
    def current(self):
        return self._current

    @current.setter
    def current(self, value):
        self._current = value

    @property
    def result(self):
        return self._result

    def update(self, connection_data):
        self._current = connection_data.current

    def reset(self):
        self._current = 0
        self._result.reset()

    def __str__(self):
        return str({"connection_id": self.connection_id, 'current': self.current, 'result': self._result})


class ConnectionDataCollection(object):
    def __init__(self, comparable_entry_factory):
        self._comparable_entry_factory = comparable_entry_factory
        self._connection_data_items = {}
        self._current_data_item = None

    def update(self, connection_data):
        pass

    def __getitem__(self, connection_id):
        return self._connection_data_items.get(connection_id)

    @property
    def connection_data_items(self):
        return self._connection_data_items

    @property
    def current_data(self):
        return self._current_data_item

    @property
    def result(self):
        return MultipleConnectionDataResult(
            [connection_data.result for _, connection_data in self._connection_data_items.items()])

    def reset(self):
        pass


class DynamicConnectionDataCollection(ConnectionDataCollection):
    def __init__(self, comparable_entry_factory):
        super(DynamicConnectionDataCollection, self).__init__(comparable_entry_factory)

    def update(self, data_entry):
        comparable_entry = self._comparable_entry_factory.create(data_entry)
        connection_data_item = ConnectionDataItem(comparable_entry.connection.conn_id, current=comparable_entry)
        self._update(connection_data_item)

        self._current_data_item = self.get_data_item(comparable_entry.connection.conn_id)
        return comparable_entry

    def _update(self, connection_data_item):

        if connection_data_item.connection_id in self._connection_data_items:
            self._connection_data_items[connection_data_item.connection_id].update(connection_data_item)
        else:
            self._connection_data_items[connection_data_item.connection_id] = connection_data_item

    def get_data_item(self, connection_id):
        return self._connection_data_items.get(connection_id)

    def reset(self):
        self._current_data_item = None
        for item in self._connection_data_items.values():
            item.reset()
        self._connection_data_items.clear()

    def finalize(self):
        pass


def is_last_entry(data_entry, data_item):
    if not data_item:
        return False

    if not data_item.result.total:
        return False

    return ((data_entry.interval.interval_start == 0.0)
            and (data_entry.interval.diff >= data_item.result.total.interval.diff))


class IperfDynamicConnectionDataCollectionWithoutConclusion(DynamicConnectionDataCollection):
    def __init__(self, comparable_entry_factory):
        super(IperfDynamicConnectionDataCollectionWithoutConclusion, self).__init__(comparable_entry_factory)

    def update(self, data_entry):
        data_item = self.get_data_item(data_entry.connection.conn_id)
        if is_last_entry(data_entry, data_item):
            return None
        return super(IperfDynamicConnectionDataCollectionWithoutConclusion, self).update(data_entry=data_entry)


class IperfDynamicConnectionDataCollection(DynamicConnectionDataCollection):
    def __init__(self, comparable_entry_factory, conclusion_entry_factory):
        super(IperfDynamicConnectionDataCollection, self).__init__(comparable_entry_factory)
        self._conclusion_entry_factory = conclusion_entry_factory
        self._conclusion_entries = {}

    @property
    def conclusion_entry_factory(self):
        return self._conclusion_entry_factory

    @property
    def conclusion_entries(self):
        return self._conclusion_entries

    def update(self, data_entry):
        data_item = self.get_data_item(data_entry.connection.conn_id)
        if is_last_entry(data_entry, data_item):
            conclusion_entry_data = self._conclusion_entry_factory.create(data_entry)
            self.conclusion_entries[data_entry.connection.conn_id] = conclusion_entry_data
            return None
        return super(IperfDynamicConnectionDataCollection, self).update(data_entry=data_entry)

    def finalize(self):
        for conn_id, entry in self._conclusion_entries.items():
            connection_data_item = self.connection_data_items[conn_id]
            connection_data_item.result.total = entry
